#!/usr/bin/env python3
"""gen_ypcb_00338_1p1_man.py - writes docs/man/ypcb-00338-1p1.man.json, the MAN file for the Kintex-7 card YPCB-00338-1P1 (XC7K480T), 2 Nov 2026 (Alan 18:02: the Kintex needs a MAN file).

HOW THIS FILE WAS MADE, stated plainly: from WRITTEN RECORDS only, not from a chip database and not from the card.  Sources: the project note claude/kintex-card-flow.md (24 and 25 Oct 2026),
fpga/ypcb/hexn/hexn.xdc (the pins of designs that ran on the card), docs/hex-n/HEXN_DESIGN.md (part and speed grade of the Kintex sweep, nextpnr sizes).  Alan mentioned a user frontend for MAN
creation; it was NOT found in this branch or in the project documents, so nothing was taken from it.  Every figure not in those records is null, never a guess: LUT4 total, native width, nowidelut, JTAG idcode.
VERSION 2 (same day): resource counts and the package pin table now come from the chip database file (docs/man/data/xc7k480tffg1156.chipdb_facts.json).  It follows the Tang Nano 20K file's shape (man_version, card_id, vendor, synthesis, device, board, capabilities, verification,
provenance) so the vendor-neutral reader flexsub_assemble_v1.load_man_flexsub accepts it; the Quartus reader refuses it clearly, as it does for the Tang."""
import json, os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
OUT = os.path.join(ROOT, "docs", "man", "ypcb-00338-1p1.man.json")
FACTS = os.path.join(ROOT, "docs", "man", "data", "xc7k480tffg1156.chipdb_facts.json")        # made by tools/man_gen/bba_read_v1.py from the chip database


def build():
    cf = json.load(open(FACTS)); st = cf["sites"]
    return {
        "man_version": "1.1",
        "card_id": "ypcb-00338-1p1-kintex7-xc7k480t",
        "generated": "2026-11-02",
        "generated_by": "GENERATED by tools/man_gen/gen_ypcb_00338_1p1_man.py (Claude). Chip facts read from the openXC7 chip database xc7k480tffg1156.bba by tools/man_gen/bba_read_v1.py (version 2 of this file, 2 Nov 2026; version 1 had only written records); board facts from written records. NOT produced from the card, NOT checked against any schema tool.",
        "vendor": "xilinx",
        "synthesis": {
            "tool": "openXC7 open flow: yosys -> nextpnr-xilinx -> bitstream (xc7-build.sh of Alan's ypcb-00338-1p1 repo)",
            "nowidelut": {"supported": None, "default": None, "note": "not checked for the Xilinx flow; the Gowin option does not apply here"},
            "chipdb_note": "the build needs CHIPDB set to a prebuilt xc7k480tffg1156.bin; without it a build ran over 6 hours and never reached the design",
            "source": "claude/kintex-card-flow.md",
        },
        "cell_costs": {
            "unit": "none recorded for this card: the project's [LUT4, ALU, DFF, MULT] table is a Gowin count and does not transfer",
            "for_scale_only_hexn_nextpnr": {"64_cells_lut_sites": 31428, "128_cells_lut_sites": 49300, "255_cells_lut_sites": 86459, "255_cells_ff": 22240,
                                            "source": "claude/kintex-card-flow.md, Hex-N cells (not UniCell); about, estimates from nextpnr, not silicon"},
        },
        "device": {
            "part": "XC7K480T", "family": "Xilinx Kintex-7", "package": "FFG1156", "speed_grade": "-1",
            "speed_grade_source": "docs/hex-n/HEXN_DESIGN.md Kintex sweep (xc7k480tffg1156-1)",
            "toolchain_open_flow": "openXC7 (yosys, nextpnr-xilinx), load with openFPGALoader",
            "jtag_idcode": None,
            "logic": {"unit": "LUT sites (nextpnr SLICE_LUTX)", "lut_sites_nextpnr": cf["slice_lut_sites"], "lut6_yosys": 298600, "slices": st["SLICE"], "lut4_total": None, "ff_total": cf["slice_ff_sites"], "native_width": None,
                      "note": "use the nextpnr figure for how much of the chip is used; the yosys LUT6 count is a different measure (claude/kintex-card-flow.md)"},
            "dsp": {"total_blocks": st["DSP48"], "primitives": [], "abilities": [], "note": "DSP48 sites read from the chip database; the primitive list and abilities are not recorded"},
            "bram": {"total_blocks": st["RAMB36"], "ramb18_sites": st["RAMB18"], "note": "RAMB36 sites; each can be two RAMB18"},
            "other_sites": {k: st[k] for k in ("IOB", "GTXE2_CHANNEL", "MMCME2_ADV", "PLLE2_ADV", "BUFGCTRL", "BUFHCE", "IDELAY", "ILOGIC", "OLOGIC", "PCIE", "IPAD", "OPAD") if k in st},
            "package_pins": {"package": "ffg1156", "pads": len(cf["pads"]), "unique_pin_names": len({p["pin"] for p in cf["pads"]}),
                             "note": "every pad of the FFG1156 package record: pin name, tile, site. A pin existing here does NOT say the card wires it that way.",
                             "table": {p["pin"]: {"tile": p["tile"], "site": p["site"]} for p in cf["pads"]}},
        },
        "board": {
            "name": "YPCB-00338-1P1", "clock": {"SYS_CLK": {"pin": "AA28", "io_standard": "LVCMOS18", "freq_hz": 50000000, "source": "fpga/ypcb/hexn/hexn.xdc; 50 MHz from the card-flow note"}},
            "leds": {"led[0]": "P30", "led[1]": "M30", "led[2]": "N30", "io_standard": "LVCMOS18", "source": "fpga/ypcb/hexn/hexn.xdc"},
            "ddr3": {"channels": 2, "width_bits": 72, "data_bits": 64, "ecc_bits": 8, "size_gib_each": 2, "chip": "MT41K256M8",
                     "controller_note": "UberDDR3 (GPL) works under openXC7 at DDR3-667; kept out of every repo"},
            "jtag": {"cable": "Digilent HS3 (openFPGALoader -c digilent_hs2)", "tck_hz": 10000000, "user_chain_codes": {"USER1": "0x02", "USER2": "0x03", "USER3": "0x22", "USER4": "0x23"},
                     "note": "ypcb DDR3 debug uses USER1; the Hex-N bridge was moved to USER2 for the joint design"},
            "pcie": "side is dead; JTAG works",
            "pins_recorded": "board wiring: only SYS_CLK and led[2:0]; the package pins of the chip are in device.package_pins (what the chip has, not what the card connects)",
            "do_not": ["never pull pin AC24 down", "never program fuses", "back up the flash before writing it"],
        },
        "capabilities": {"bram": True, "dsp": True, "ddr3": True, "jtag_user_chains": True, "pcie": False, "sd_card": None, "spi_flash_onboard": None,
                         "note": "null = not recorded in the sources, not 'no'"},
        "verification": {"chip_database": "read: xc7k480tffg1156.bba (openXC7). Slices 74,650 and LUT sites 597,200 equal the figure nextpnr gave in the card-flow note; DSP48 1,920, RAMB36 955, IOB 400, GTX channels 32 are as the database lists them and were not checked against a datasheet; AA28, P30, M30, N30 and AC24 exist in the package table", "on_card": "the pins above are from designs that ran on the card (Hex-N ladder, DDR3 probe, joint design, 24 and 25 Oct 2026); the rest is as written in the card-flow note",
                         "unverified": ["speed grade (from a ledger row, not the database)", "the yosys LUT6 figure (from a note)", "everything marked null"]},
        "provenance": ["docs/man/data/xc7k480tffg1156.chipdb_facts.json (from the chip database by tools/man_gen/bba_read_v1.py)", "claude/kintex-card-flow.md (24 Oct 2026, updated 25 Oct)", "fpga/ypcb/hexn/hexn.xdc", "docs/hex-n/HEXN_DESIGN.md (Kintex size and speed sweep, 23 Oct 2026)"],
    }


if __name__ == "__main__":
    with open(OUT, "w") as f:
        json.dump(build(), f, indent=2, sort_keys=False); f.write("\n")
    print("wrote", OUT)
